def gen(rng):
    def fmt(n, edges):
        return f"{n}\n" + '\n'.join(f"{u} {v}" for u, v in edges)
    def random_tree(n, kind):
        perm = list(range(n))
        rng.shuffle(perm)
        edges = []
        for i in range(1, n):
            if kind == 'rand':
                p = rng.randrange(i)
            elif kind == 'path':
                p = i - 1
            elif kind == 'star':
                p = 0
            elif kind == 'cat':
                p = i - 1 if i % 2 == 1 else max(0, i - 2)
            else:
                p = (i - 1) // 2
            a, b = perm[i], perm[p]
            edges.append((a, b) if rng.random() < 0.5 else (b, a))
        rng.shuffle(edges)
        return edges
    tests = [
        fmt(2, [(0, 1)]),
        fmt(2, [(1, 0)]),
        fmt(3, [(0, 1), (1, 2)]),
        fmt(3, [(1, 2), (0, 1)]),
        fmt(4, [(0, 1), (1, 2), (2, 3)]),
        fmt(5, [(0, 1), (0, 2), (0, 3), (0, 4)]),
        fmt(5, [(4, 0), (3, 0), (2, 0), (1, 0)]),
    ]
    for n in (2, 3, 4, 5, 6, 8, 10, 12, 15, 20):
        for kind in ('rand', 'path', 'star', 'cat', 'bin'):
            if n <= 8 and kind == 'bin' and n < 3:
                continue
            tests.append(fmt(n, random_tree(n, kind)))
    N = 100000
    for kind in ('rand', 'path', 'star', 'cat', 'bin'):
        tests.append(fmt(N, random_tree(N, kind)))
    return tests
